export function BookmarkForm({ initial, onClose, onSaved, onEditExisting }: { initial?: Bookmark; onClose: () => void; onSaved: (bookmark: Bookmark) => void; onEditExisting: (bookmark: Bookmark) => void }) {
  const [form, setForm] = useState(initial ? { url: initial.url, title: initial.title, notes: initial.notes, tags: initial.tags.map(t=>t.name).join(', '), isFavorite: initial.isFavorite } : blank);
