  return <><div className="dialog-backdrop" role="presentation"><form className="dialog bookmark-form" role="dialog" aria-modal="true" aria-labelledby="form-title" onSubmit={submit}>
    <header className="dialog-header"><div><p className="eyebrow">{initial ? 'Make a change' : 'Add to your collection'}</p><h2 id="form-title">{initial ? 'Edit bookmark' : 'Save something good'}</h2></div><button type="button" className="icon-button" aria-label="Close" onClick={onClose}>×</button></header>
