    <label>Tags <span className="optional">Comma separated</span><input value={form.tags} onChange={(e)=>setForm({...form,tags:e.target.value})} placeholder="design, reading, inspiration"/>{fieldErrors.tags&&<small className="field-error">{fieldErrors.tags}</small>}</label>
    <label className="check-row"><input type="checkbox" checked={form.isFavorite} onChange={(e)=>setForm({...form,isFavorite:e.target.checked})}/><span>Mark as a favorite</span></label>
    {error&&<p className="form-error" role="alert">{error}</p>}
