:root {
  color-scheme: light;
  --ink: #20231d;
  --muted: #6d7167;
  --paper: #f6f2e9;
  --card: #fffdf8;
  --line: #dcd6c9;
  --sage: #314f40;
  --sage-2: #47705b;
  --gold: #d7a84a;
  --clay: #b94d3c;
  --shadow: 0 18px 50px rgba(44, 50, 40, .12);
  --radius: 18px;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-synthesis: none;
}

