.muted { color: var(--muted); line-height: 1.55; }
.button { border: 1px solid transparent; border-radius: 999px; padding: .78rem 1.25rem; cursor: pointer; font-weight: 750; transition: .18s ease; text-decoration: none; display: inline-flex; justify-content: center; align-items: center; gap: .4rem; }
.button:hover { transform: translateY(-1px); }
