.button.primary { background: var(--sage); color: white; box-shadow: 0 8px 20px rgba(49,79,64,.2); }
.button.primary:hover { background: #254234; }
.button.ghost { background: transparent; border-color: var(--line); }
.button.danger { background: var(--clay); color: white; }
