.text-button { border: 0; background: transparent; color: var(--sage); padding: 0; font-weight: 800; cursor: pointer; text-decoration: underline; text-underline-offset: 3px; }
.app-loading { min-height: 100vh; display: grid; place-content: center; text-align: center; color: var(--muted); gap: .5rem; }

