await page.getByLabel('Password').fill('correct horse battery staple');
await page.getByRole('button', { name: 'Create account' }).click();
for (const [url,title,tags,note] of [
  ['https://www.nationalgeographic.com/travel','Slow travel, deep places','Travel, Reading','A thoughtful piece to revisit before the next trip.'],
  ['https://developer.mozilla.org','MDN Web Docs','Reference, Web','The dependable reference shelf.'],
  ['https://www.seriouseats.com','The science of better cooking','Cooking, Favorite','Techniques worth trying this weekend.']
]) {
  await page.getByRole('button',{name:/add bookmark/i}).click();
  await page.getByLabel(/web address/i).fill(url);
  await page.getByLabel(/title/i).fill(title);
  await page.getByLabel(/notes/i).fill(note);
  await page.getByLabel(/tags/i).fill(tags);
  await page.getByRole('button',{name:'Save bookmark'}).click();
}
await page.screenshot({ path: '/tmp/keepsake-review.png', fullPage: true });
await browser.close();
